import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();
  const [bookingHistory, setBookingHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [greeting, setGreeting] = useState("");

  const menuItems = [
    { name: "Home", route: "/home" },
    { name: "Settings", route: "/settings" },
    { name: "Profile", route: "/profile" }, 
    { name: "About", route: "/about" },
    { name: "Logout", route: "/" }
  ];

  useEffect(() => {
    const userId = localStorage.getItem("userId");
    if (!userId) return;

    axios
      .get(`/api/booking-history`)
      .then((res) => {
        const userHistory = res.data.filter((h) => h.changedBy?.id == userId);
        setBookingHistory(userHistory);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching booking history:", err);
        setLoading(false);
      });
  }, []);

  useEffect(() => {
    const updateGreeting = () => {
      const hours = new Date().getHours();
      if (hours < 12) setGreeting("Good Morning");
      else if (hours < 18) setGreeting("Good Afternoon");
      else setGreeting("Good Evening");
    };

    updateGreeting();
    const interval = setInterval(updateGreeting, 60 * 1000);
    return () => clearInterval(interval);
  }, []);

  const handleMenuClick = (item) => {
    if (item.name === "Logout") {
      localStorage.clear();
      navigate("/");
    } else {
      navigate(item.route);
    }
  };

  const userName = localStorage.getItem("username") || "";

  return (
    <div className="homepage-container">
      <aside className="sidebar">
        <div className="sidebar-logo">Parking System</div>
        {menuItems.map((item, index) => (
          <button
            key={index}
            className="sidebar-btn"
            onClick={() => handleMenuClick(item)}
          >
            {item.name}
          </button>
        ))}
      </aside>

      <div className="content-wrapper">
        <main className="main-content">
          <section className="hero-section">
            <h1>Welcome to Parking Slot System</h1>
            <p>
              Manage your bookings, view facilities, and update your profile all
              in one place.
            </p>
            <button className="start-btn" onClick={() => navigate("/booking")}>
              Start Booking
            </button>
          </section>

          <section className="dashboard-cards">
            <div className="card">
              <h2>Booking History</h2>
              {loading ? (
                <p>Loading history...</p>
              ) : bookingHistory.length === 0 ? (
                <p>No history yet. Start booking to see updates here!</p>
              ) : (
                <ul>
                  {bookingHistory.slice(0, 5).map((history) => (
                    <li key={history.historyId}>
                      <strong>{history.booking?.slotName || "Slot"}:</strong>{" "}
                      {history.statusChange} on{" "}
                      {new Date(history.changeDate).toLocaleString()}
                    </li>
                  ))}
                </ul>
              )}
              <button onClick={() => navigate("/booking-history")}>
                View Full History
              </button>
            </div>

            <div className="card">
              <h2>Facilities</h2>
              <p>
                Check available parking facilities, capacity, and other details.
              </p>
              <button onClick={() => navigate("/facilities")}>
                View Facilities
              </button>
            </div>

            <div className="card">
              <h2>Profile</h2>
              <p>Update your personal information and preferences.</p>
              <button onClick={() => navigate("/profile")}>Go to Profile</button>
            </div>
          </section>
        </main>
      </div>
    </div>
  );
}

export default HomePage;
